namespace ghidra.app.plugin.core.decompiler.export;





using ghidra.util;

public class PcodeDatabase {
	private static readonly char DBSEP = '\t';
	private static readonly char EOL = '\n';

	protected Map<string, Collection<List<string>>> contents = new();

	public void writeFile(Collection<List<string>> contentList, string predicateFile,
			string directory)
    {
		File factsFile = new File(directory, predicateFile + ".facts");
		Writer w = new BufferedWriter(new FileWriter(factsFile, true));
		foreach (List<string> record in {
			writeRecord(w, record);
		}
		w.flush();
		w.close();
	}

	public void writeFacts(string directory, bool writeAll) {
		int k = Runtime.getRuntime().availableProcessors() * 2 - 1;
		ExecutorService es = Executors.newFixedThreadPool(k);
		foreach (string fn in contents.keySet()) {
			es.execute(() => {
				try {
					writeFile(contents.get(fn), fn, directory);
				}
				catch (Exception e) {
					// System.out.println(e);
					ghidra.util.Msg.info(this, e);
					foreach (StackTraceElement st in e.getStackTrace()) {
						ghidra.util.Msg.info(this, st);
					}
				}
			});
		}

		es.shutdown();
		try {
			while (!es.awaitTermination(30, TimeUnit.SECONDS))
				;
		}
		catch (Exception e) {
			// System.out.println(e);
			Msg.info(this, e);
			foreach (StackTraceElement st in e.getStackTrace()) {
				ghidra.util.Msg.info(this, st);
			}
		}

		this.clear(writeAll);
	}

	private void writeRecord(Writer writer, List<string> record)
    {
		bool first = true;
		foreach (string col in record) {
			if (col == null) {
				col = "UNKNOWN";
			}
			if (!first) {
				writer.write(DBSEP);
			}
			writeColumn(writer, col);
			first = false;
		}
		writer.write(EOL);
	}

	private void writeColumn(Writer writer, string column)
    {
		// Quote some special characters.
		for (int i = 0; i < column.length(); i++) {
			char c = column.charAt(i);
			switch (c) {
				case '\"': return writer.write("'");
				case '\\': {
					writer.write('\\');
					writer.write('\\');
				}
				case EOL: {
					writer.write('\\');
					writer.write('n');
				}
				case '\t': {
					writer.write('\\');
					writer.write('t');
				}
				default: writer.write(c);
			}
		}
	}

	public void addExport(string filename, params string[] args) {
		this.contents.computeIfAbsent(filename, _ => new())
				.add(Arrays.asList(args));
	}

	public void clear(bool clearAll) {
		contents = new();
	}
}
